import org.apache.ignite.configuration.ClientConfiguration; import org.apache.ignite.client.events.*; import org.apache.ignite.logger.java.JavaLogger;
ConnectionEventListener connectionListener = new ConnectionEventListener() {
    @Override public void onHandshakeFail(HandshakeFailEvent e) { System.out.println("handshake failed: " + e.throwable()); }
    @Override public void onConnectionClosed(ConnectionClosedEvent e) { System.out.println("closed: " + e.connectionDescription().remoteAddress() + " " + e.throwable()); }
};
RequestEventListener requestListener = new RequestEventListener() {
    @Override public void onRequestFail(RequestFailEvent e) { System.out.println("request failed: " + e.operationName() + " id " + e.requestId() + ": " + e.throwable()); }
};
ClientConfiguration cfg = new ClientConfiguration().setAddresses("127.0.0.1:10800")
    .setLogger(new JavaLogger())
    .setEventListeners(connectionListener, requestListener);
Both listener interfaces have only default methods (onHandshakeStart, onHandshakeSuccess, onHandshakeFail, onConnectionClosed; onRequestStart, onRequestSuccess, onRequestFail): override the ones you need. new JavaLogger() logs through the java.util.logging root logger, so debug lines such as Handshake succeeded appear only when the root logger and its console handler are set to FINE.
